using GaoApp.Web.Services.Assistant;
using GaoApp.Web.Services.CustomerService;
using Xunit;

namespace GaoApp.Tests.Security;

public sealed class CustomerServiceStoreTests:IDisposable
{
    private readonly string directory=Path.Combine(Path.GetTempPath(),"GaoCskhTests",Guid.NewGuid().ToString("N"));
    private readonly AssistantIntegrationTests.FixedClock clock=new();
    private readonly AssistantIntegrationTests.Monitor<CustomerServiceOptions> options=new(new(){DatabasePath="customer.db"});
    private CustomerServiceStore Store()=>new(new AssistantIntegrationTests.EnvironmentStub(directory),options,clock);
    private readonly Guid visitor=Guid.NewGuid();
    private static readonly CustomerStaff Agent=new(1,1,"Lan",true,false),Other=new(2,1,"An",true,false),Manager=new(3,1,"Quản lý",false,true);
    private CustomerConversation Start(CustomerServiceStore s,int store=1,Guid? owner=null){s.Configure(store,true,s.Settings(store).Version);return s.Start(store,owner??visitor,new(Guid.NewGuid(),"Khách TEST","contact-test",true));}
    private static CustomerCommand Cmd(string action,CustomerConversation c,string? message=null)=>new(Guid.NewGuid(),action,c.Version,message);
    [Fact]public void New_public_store_is_disabled_and_requires_explicit_consent(){var s=Store();Assert.False(s.Settings(1).Enabled);Assert.Equal(404,Assert.Throws<AssistantException>(()=>s.Start(1,visitor,new(Guid.NewGuid(),"Khách",null,true))).Status);s.Configure(1,true,0);Assert.Equal(400,Assert.Throws<AssistantException>(()=>s.Start(1,visitor,new(Guid.NewGuid(),"Khách",null,false))).Status);}
    [Fact]public void Visitors_stores_and_staff_are_isolated_and_contact_is_not_an_identity(){var s=Store();var c=Start(s);Assert.Equal(404,Assert.Throws<AssistantException>(()=>s.Get(1,Guid.NewGuid(),c.Id)).Status);s.Configure(2,true,0);Assert.Equal(404,Assert.Throws<AssistantException>(()=>s.Get(2,visitor,c.Id)).Status);Assert.Equal(404,Assert.Throws<AssistantException>(()=>s.StaffGet(Other with{StoreId=2},c.Id)).Status);Assert.Empty(s.Mine(1,Guid.NewGuid()));Assert.Equal(c.Id,s.Get(1,visitor,c.Id).Id);}
    [Fact]public void Start_and_message_retries_preserve_one_transcript_and_reject_changed_payload(){var s=Store();s.Configure(1,true,0);var input=new CustomerStart(Guid.NewGuid(),"Khách",null,true);var c=s.Start(1,visitor,input);Assert.Equal(c.Id,s.Start(1,visitor,input).Id);var send=new CustomerSend(Guid.NewGuid(),"giá sữa");var t=s.Begin(1,visitor,c.Id,send);Assert.True(t.RunAi);Assert.False(s.Begin(1,visitor,c.Id,send).RunAi);Assert.Equal(409,Assert.Throws<AssistantException>(()=>s.Begin(1,visitor,c.Id,send with{Message="Khác"})).Status);var who=new CustomerBridgeIdentity(visitor,1,c.Id,send.RequestId);Assert.True(s.BridgeAllowed(who));var done=s.Complete(who,"TEST giá lẻ","{}",null);Assert.Equal(3,done.Messages.Length);Assert.Equal(3,s.Complete(who,"DUPLICATE","{}",null).Messages.Length);}
    [Theory][InlineData("handoff")][InlineData("claim")]
    public void Human_takeover_fences_late_ai_and_revokes_its_data_bridge(string action){var s=Store();var c=Start(s);var send=new CustomerSend(Guid.NewGuid(),"hỏi sản phẩm");s.Begin(1,visitor,c.Id,send);var who=new CustomerBridgeIdentity(visitor,1,c.Id,send.RequestId);Assert.True(s.BridgeAllowed(who));c=s.Get(1,visitor,c.Id);if(action=="handoff")c=s.Handoff(1,visitor,c.Id,Guid.NewGuid());else c=s.StaffCommand(Agent,c.Id,Cmd("claim",c));Assert.False(s.BridgeAllowed(who));var late=s.Complete(who,"LATE_AI_SHOULD_NOT_SHOW","{}",null);Assert.DoesNotContain(late.Messages,m=>m.Text.Contains("LATE_AI"));Assert.Equal(action=="claim"?"human":"waiting",late.Mode);}
    [Fact]public async Task Two_workers_cannot_claim_same_conversation_and_only_owner_replies(){var s=Store();var c=Start(s);var second=Store();async Task<int> Claim(CustomerServiceStore worker,CustomerStaff agent)=>await Task.Run(()=>{try{worker.StaffCommand(agent,c.Id,Cmd("claim",c));return 200;}catch(AssistantException e){return e.Status;}});var results=await Task.WhenAll(Claim(s,Agent),Claim(second,Other));Assert.Equal(new[]{200,409},results.Order().ToArray());c=s.StaffGet(Agent,c.Id);var owner=c.Owner==1?Agent:Other;var notOwner=c.Owner==1?Other:Agent;Assert.Equal(409,Assert.Throws<AssistantException>(()=>s.StaffCommand(notOwner,c.Id,Cmd("reply",c,"Sai nhân viên"))).Status);var input=Cmd("reply",c,"TEST: Đã nhận yêu cầu.");var first=s.StaffCommand(owner,c.Id,input);Assert.Equal(first.Messages.Length,s.StaffCommand(owner,c.Id,input).Messages.Length);Assert.Single(first.Messages,m=>m.Role=="agent");}
    [Fact]public void Manager_can_release_others_without_sending_messages_or_broad_employee_assistant_rights(){var s=Store();var c=Start(s);c=s.StaffCommand(Agent,c.Id,Cmd("claim",c));Assert.Equal(403,Assert.Throws<AssistantException>(()=>s.StaffCommand(Manager,c.Id,Cmd("reply",c,"Không được gửi"))).Status);c=s.StaffCommand(Manager,c.Id,Cmd("release",c));Assert.Equal("waiting",c.Mode);Assert.Null(c.Owner);}
    [Fact]public void Crash_lease_recovery_is_visible_in_waiting_inbox_without_customer_reopening(){var s=Store();var c=Start(s);var send=new CustomerSend(Guid.NewGuid(),"TEST hỏi");s.Begin(1,visitor,c.Id,send);clock.Now=clock.Now.AddSeconds(121);var recreated=Store();var rows=recreated.Inbox(Agent,"waiting");Assert.Equal(c.Id,Assert.Single(rows).Id);Assert.Equal("ai_interrupted",rows[0].HandoffReason);Assert.False(recreated.BridgeAllowed(new(visitor,1,c.Id,send.RequestId)));}
    [Fact]public void Return_to_bot_resets_context_and_closed_chat_cannot_accept_new_messages(){var s=Store();var c=Start(s);c=s.StaffCommand(Agent,c.Id,Cmd("claim",c));c=s.StaffCommand(Agent,c.Id,Cmd("bot",c));var send=new CustomerSend(Guid.NewGuid(),"mặt hàng mới");var turn=s.Begin(1,visitor,c.Id,send);Assert.True(turn.RunAi);Assert.Equal("",turn.StateJson);c=s.StaffGet(Agent,c.Id);c=s.StaffCommand(Manager,c.Id,Cmd("close",c));Assert.Equal("closed",c.Mode);Assert.Equal(409,Assert.Throws<AssistantException>(()=>s.Begin(1,visitor,c.Id,new(Guid.NewGuid(),"thêm"))).Status);}
    [Fact]public void Retention_removes_transcript_context_and_request_ids(){var s=Store();var c=Start(s);clock.Now=clock.Now.AddDays(7).AddSeconds(1);s.Purge();Assert.Empty(s.Inbox(Agent,"all"));Assert.Equal(404,Assert.Throws<AssistantException>(()=>s.Get(1,visitor,c.Id)).Status);}
    [Fact]public void Ending_device_session_revokes_bridge_and_preserves_history_for_staff_only(){var s=Store();var c=Start(s);var send=new CustomerSend(Guid.NewGuid(),"hỏi");s.Begin(1,visitor,c.Id,send);s.Revoke(new(visitor,1,clock.Now.AddDays(7)));Assert.True(s.Revoked(1,visitor));Assert.False(s.BridgeAllowed(new(visitor,1,c.Id,send.RequestId)));Assert.Equal("closed",s.StaffGet(Agent,c.Id).Mode);}    public void Dispose(){if(Directory.Exists(directory))Directory.Delete(directory,true);}
}